# Archivo generado automáticamente con la plantilla index.html comprimida
import gzip
import base64

_COMPRESSED_INDEX_HTML = """"""

def get_default_index_html() -> str:
    """Devuelve el contenido HTML de respaldo descomprimido."""
    raw_bytes = base64.b64decode(_COMPRESSED_INDEX_HTML)
    return gzip.decompress(raw_bytes).decode('utf-8')
